<article class="analytics-card"><x-analytics.card-header title="Fleet Availability" description="Current Bus Master List status."/><div class="analytics-availability-layout"><div class="availability-score"><div class="availability-ring" style="--availability-angle: {{ min(360,max(0,($fleet['fleetAvailability']??0)*3.6)) }}deg;"><div class="availability-ring-center"><strong>{{ number_format($fleet['fleetAvailability']??0,1) }}%</strong><span>Active</span></div></div></div><div class="availability-breakdown"><div class="availability-row"><div><span>Active</span></div><strong>{{ $fleet['activeBuses']??0 }}</strong></div><div class="availability-row"><div><span>Maintenance</span></div><strong>{{ $fleet['underMaintenance']??0 }}</strong></div><div class="availability-row"><div><span>Other</span></div><strong>{{ $fleet['inactiveBuses']??0 }}</strong></div><div class="availability-total"><span>Total Buses</span><strong>{{ $fleet['totalBuses']??0 }}</strong></div></div></div></article>